package com.pabonaki.model;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;@Document("categories")public class Category{@Id private String id;@Indexed(unique=true)private String name;private String slug;private String description;private boolean active=true;public String getId(){return id;}public void setId(String v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getSlug(){return slug;}public void setSlug(String v){slug=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}}